package com.brightloop.subscription;
import com.brightloop.catalog.*;import com.brightloop.discount.*;import com.brightloop.plan.*;import com.brightloop.quotation.Quotation;import com.brightloop.tax.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class SubscriptionService{
 private final SubscriptionRepository subs;private final CustomerRepository customers;private final PlanRepository plans;private final ProductVariantRepository variants;private final TaxRepository taxes;private final DiscountRepository discounts;
 public SubscriptionService(SubscriptionRepository s,CustomerRepository c,PlanRepository p,ProductVariantRepository v,TaxRepository t,DiscountRepository d){subs=s;customers=c;plans=p;variants=v;taxes=t;discounts=d;}
 @Transactional(readOnly=true) public List<SubscriptionDtos.Response> list(){return subs.findAll().stream().sorted(Comparator.comparing(Subscription::getId).reversed()).map(SubscriptionDtos.Response::of).toList();}
 @Transactional(readOnly=true) public SubscriptionDtos.Response get(Long id){return SubscriptionDtos.Response.of(find(id));}
 @Transactional public SubscriptionDtos.Response create(SubscriptionDtos.Request r){var plan=plan(r.planId());var customer=customers.findById(r.customerId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found"));validate(plan,r.startDate(),r.expiryDate(),r.quantity());var variant=r.variantId()==null?null:variants.findById(r.variantId()).filter(v->v.getProduct().getId().equals(plan.getProduct().getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Variant does not belong to the plan product"));BigDecimal unit=plan.getBillingPrice().add(variant==null?BigDecimal.ZERO:variant.getAdditionalPrice()).setScale(2,RoundingMode.HALF_UP);BigDecimal base=unit.multiply(BigDecimal.valueOf(r.quantity())).setScale(2,RoundingMode.HALF_UP);TaxCalc tax=tax(plan.getProduct().getId(),base,r.quantity(),LocalDate.now());Discount disc=discount(r.discountCode());BigDecimal discAmount=discountAmount(disc,base);BigDecimal total=base.add(tax.amount).subtract(discAmount).max(BigDecimal.ZERO);String number=number("SUB");Subscription s=new Subscription(number,customer,plan,r.startDate(),r.expiryDate(),r.paymentTerms(),r.quantity(),unit,base,tax.amount,discAmount,total);s.setDiscount(disc);s.addLine(new SubscriptionLine(s,plan.getProduct(),variant,plan.getName(),r.quantity(),unit,tax.rate));return SubscriptionDtos.Response.of(subs.save(s));}
 @Transactional public SubscriptionDtos.Response fromQuotation(Quotation q){var first=q.getLines().stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quotation has no lines"));if(first.getPlan()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Every converted quotation line needs a subscription plan");for(var line:q.getLines())if(line.getPlan()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Every converted quotation line needs a subscription plan");LocalDate start=LocalDate.now();Plan primary=first.getPlan();Subscription s=new Subscription(number("SUB"),q.getCustomer(),primary,start,null,q.getPaymentTerms(),first.getQuantity(),first.getUnitPrice(),q.getSubtotal(),q.getTaxAmount(),q.getDiscountAmount(),q.getGrandTotal());s.setDiscount(q.getDiscount());s.confirm();for(var line:q.getLines())s.addLine(new SubscriptionLine(s,line.getProduct(),line.getVariant(),line.getPlan().getName(),line.getQuantity(),line.getUnitPrice(),line.getTaxRate()));return SubscriptionDtos.Response.of(subs.save(s));}
 @Transactional public SubscriptionDtos.Response action(Long id,String action){Subscription s=find(id);try{switch(action){case "confirm"->s.confirm();case "activate"->{if(LocalDate.now().isBefore(s.getStartDate()))throw new IllegalStateException("Subscription cannot activate before its start date");s.activate();}case "pause"->s.pause();case "resume"->s.resume();case "close"->s.close(false);case "terminate"->s.close(true);case "renew"->s.renew();default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown subscription action");}}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}return SubscriptionDtos.Response.of(s);}
 @Transactional(readOnly=true) public List<SubscriptionDtos.Response> own(String email){return customers.findByEmailIgnoreCase(email).map(c->subs.findByCustomerId(c.getId()).stream().map(SubscriptionDtos.Response::of).toList()).orElseGet(List::of);}
 @Transactional public SubscriptionDtos.Response ownAction(String email,Long id,String action){var customer=customers.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer profile not found"));var sub=find(id);if(!sub.getCustomer().getId().equals(customer.getId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Subscription not found");if(!List.of("pause","resume","close").contains(action))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This subscription action is not available in the portal");return action(id,action);}
 private void validate(Plan p,LocalDate start,LocalDate end,int qty){if(!"ACTIVE".equals(p.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Plan is not active");if(qty<p.getMinimumQuantity())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity is below the plan minimum");if(end!=null&&end.isBefore(start))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Expiry must be on or after the start date");LocalDate today=LocalDate.now();if(p.getAvailableFrom()!=null&&today.isBefore(p.getAvailableFrom())||p.getAvailableUntil()!=null&&today.isAfter(p.getAvailableUntil()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Plan is outside its availability window");}
 private TaxCalc tax(Long product,BigDecimal base,int qty,LocalDate date){BigDecimal amount=BigDecimal.ZERO,rate=BigDecimal.ZERO;for(Tax t:taxes.findAll()){if(!t.isActive()||t.getProduct()!=null&&!t.getProduct().getId().equals(product)||t.getEffectiveStart()!=null&&date.isBefore(t.getEffectiveStart())||t.getEffectiveEnd()!=null&&date.isAfter(t.getEffectiveEnd()))continue;if("PERCENTAGE".equals(t.getTaxType())){rate=rate.add(t.getRate());amount=amount.add(base.multiply(t.getRate()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP));}else amount=amount.add(t.getRate().multiply(BigDecimal.valueOf(qty)));}return new TaxCalc(amount,rate);}
 private Discount discount(String code){if(code==null||code.isBlank())return null;Discount d=discounts.findByCodeIgnoreCase(code.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Discount code is invalid"));if(!d.eligible(LocalDate.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Discount is not currently eligible");return d;}
 private BigDecimal discountAmount(Discount d,BigDecimal base){if(d==null)return BigDecimal.ZERO;BigDecimal amount="PERCENTAGE".equals(d.getDiscountType())?base.multiply(d.getValue()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):d.getValue();return amount.min(base);}
 private String number(String prefix){return prefix+"-"+LocalDate.now().getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();}private Plan plan(Long id){return plans.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found"));}private Subscription find(Long id){return subs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Subscription not found"));}private record TaxCalc(BigDecimal amount,BigDecimal rate){}
}
